create index if not exists delivery_proofs_created_by_idx on public.delivery_proofs(created_by); create index if not exists logistics_exceptions_assigned_to_idx on public.logistics_exceptions(assigned_to); create index if not exists logistics_exceptions_created_by_idx on public.logistics_exceptions(created_by); create index if not exists logistics_exceptions_resolved_by_idx on public.logistics_exceptions(resolved_by); create index if not exists shipment_documents_created_by_idx on public.shipment_documents(created_by); create index if not exists shipment_documents_customer_user_idx on public.shipment_documents(customer_user_id); create index if not exists shipment_tracking_events_created_by_idx on public.shipment_tracking_events(created_by); create index if not exists shipment_tracking_events_shipment_idx_v2 on public.shipment_tracking_events(shipment_id); create index if not exists shipments_customer_user_idx on public.shipments(customer_user_id); create index if not exists customer_notifications_customer_user_idx on public.customer_notifications(customer_user_id); create index if not exists quote_requests_customer_user_idx on public.quote_requests(customer_user_id); create index if not exists delivery_proofs_shipment_idx on public.delivery_proofs(shipment_id); create index if not exists shipment_documents_customer_shipment_idx on public.shipment_documents(customer_user_id, shipment_id); drop policy if exists shipment_tracking_events_customer_select on public.shipment_tracking_events; drop policy if exists shipment_tracking_events_staff_select on public.shipment_tracking_events; create policy shipment_tracking_events_customer_or_staff_select on public.shipment_tracking_events for select to authenticated using (((select private.is_staff())) or exists (select 1 from public.shipments s where s.id = shipment_tracking_events.shipment_id and s.customer_user_id = (select auth.uid())));;
